(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,n=v=>Number(v).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:2});
const types={unspecified:[L('Chưa xác định','Not specified'),L('So sánh thiết bị tại cùng lưu lượng và cột áp, theo không gian lắp đặt, khả năng bảo trì và hiệu suất tại điểm làm việc.','Compare equipment at the same flow and head, considering space, maintenance access and efficiency at duty.')],end:[L('Ly tâm hút đầu','End-suction centrifugal'),L('Cửa hút dọc trục, cửa đẩy hướng xuyên tâm. Kiểm tra bố trí đường hút, căn chỉnh và khoảng trống bảo trì.','Axial suction and radial discharge. Check suction piping, alignment and maintenance clearance.')],inline:[L('Ly tâm inline','Inline centrifugal'),L('Cửa hút và đẩy cùng trục đường ống. Kiểm tra tải lên đầu nối, giá đỡ và khoảng trống tháo động cơ.','Suction and discharge share the pipe axis. Check nozzle loads, supports and motor removal clearance.')],split:[L('Ly tâm hai phía hút','Double-suction centrifugal'),L('Hai dòng hút vào hai phía của bánh công tác. Kiểm tra bố trí đường hút, NPSH và phương án tháo bảo trì theo kết cấu của nhà sản xuất.','Two suction streams enter the impeller. Check suction arrangement, NPSH and maintenance access for the manufacturer’s construction.')],multi:[L('Đa tầng cánh','Multistage'),L('Nhiều tầng cánh nối tiếp tạo cột áp. Kiểm tra áp suất làm việc, lưu lượng tối thiểu và phương án điều khiển tăng áp.','Multiple stages generate head in series. Check pressure rating, minimum flow and pressure control strategy.')]};
const apps={chilled:[L('Tuần hoàn nước lạnh Chiller','Chilled-water circulation'),L('Với vòng kín, tính tổn thất cả đường cấp và hồi, coil và thiết bị. Chiều cao tòa nhà không cộng vào cột áp tuần hoàn; áp suất nạp tính riêng.','For a closed loop, include supply, return, coils and equipment losses. Building height is excluded from circulation head; check fill pressure separately.')],condenser:[L('Nước giải nhiệt','Condenser water'),L('Xác định hệ kín hay hệ hở theo tuyến thực tế. Tuyến tháp giải nhiệt hở cần kiểm tra chênh cao đến điểm xả và áp suất yêu cầu tại đầu phun.','Determine whether the actual circuit is closed or open. An open cooling-tower circuit requires elevation to discharge and nozzle pressure checks.')],supply:[L('Cấp nước / tăng áp','Water supply / pressure boosting'),L('Kiểm tra chênh cao, áp suất dư và áp suất nguồn. Mô hình hệ hở hiện giả thiết nguồn ở áp suất khí quyển; nguồn có áp cần được tính riêng.','Check elevation, residual pressure and source pressure. The current open-system model assumes an atmospheric source; a pressurized source needs a separate assessment.')]};
function draw(t){const vertical=t==='multi',inline=t==='inline',split=t==='split';let body=vertical?'<rect x="177" y="45" width="66" height="100" rx="8"/><path d="M180 70h60m-60 25h60m-60 25h60"/>':'<circle cx="200" cy="105" r="43"/><circle cx="200" cy="105" r="21"/><path d="M185 90l30 30m-30 0 30-30"/>';return '<svg viewBox="0 0 420 190" role="img" aria-label="'+types[t][0]+L(' — sơ đồ nguyên lý',' — schematic')+'"><g fill="#dff0eb" stroke="#588e84" stroke-width="4">'+body+'<rect x="260" y="75" width="65" height="55" rx="8"/><path d="M243 105h17M155 150h175"/></g><g fill="none" stroke="#078774" stroke-width="5"><path d="M65 105h90m-12-8 12 8-12 8"/>'+ (inline?'<path d="M243 140h105m-12-8 12 8-12 8"/>':'<path d="M200 60V25h90m-12-8 12 8-12 8"/>')+(split?'<path d="M200 170v-22m-8 12 8-12 8 12"/>':'')+'</g></svg>';}
window.HVACPumpGuide={render(x,r){const t=types[x.pumpType]?x.pumpType:'unspecified',a=apps[x.pumpApplication]?x.pumpApplication:'chilled';return '<section class="fan-selection-guide"><h3>'+L('Định hướng chọn bơm','Pump selection guidance')+'</h3><div class="fan-guide-layout">'+draw(t)+'<div><strong>'+types[t][0]+' · '+apps[a][0]+'</strong><p>'+types[t][1]+'</p></div></div><p>'+apps[a][1]+'</p>'+((a==='chilled'&&x.system==='open')||(a==='supply'&&x.system==='closed')?'<p class="field-help">'+L('Ứng dụng và loại hệ thống đang chọn có thể chưa phù hợp. Hãy kiểm tra lại Hệ kín / Hệ hở theo sơ đồ thực tế.','The selected application and system type may not match. Review Closed loop / Open system against the actual circuit.')+'</p>':'')+'<p class="fan-duty">'+L('Điểm làm việc yêu cầu','Required duty')+': <strong>Q = '+n(x.flow)+' m³/h · H = '+n(r.head)+' mH₂O</strong></p><p class="field-help">'+L('Đối chiếu đường đặc tính Q–H, hiệu suất, NPSH và dải vận hành của nhà sản xuất. Lựa chọn loại bơm không tự đổi hiệu suất hoặc công thức. Hình minh họa không theo tỷ lệ, không chọn mã sản phẩm. Chỉ tính nước sạch; chưa hỗ trợ bơm thoát nước có chất rắn.','Check manufacturer Q–H curves, efficiency, NPSH and operating range. Pump type does not automatically change efficiency or equations. Illustrations are schematic and do not select a product model. Pure water only; solids-handling drainage pumps are not supported.')+'</p><a href="https://ksbresourcecenter.com/images/downloads/Marketing/Sales_Literature/Product_Literature/KSB_Selecting_Centrifugal_Pumps.pdf" target="_blank" rel="noopener noreferrer nofollow">'+L('Tham khảo: hướng dẫn chọn bơm KSB','Reference: KSB pump selection guide')+' ↗</a></section>';}};
})();
